"""Focused spectator page; every interaction affects presentation only."""

# Match progress_dashboard.py: embedded HTML/CSS/JS is exempt from Python line width.
# ruff: noqa: E501
RUN_DASHBOARD_HTML = r"""<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>Pokémon Red · Run viewer</title>
<style>
:root{color-scheme:dark;--bg:#101216;--panel:#191d23;--border:#30363f;--text:#f0f3f5;--muted:#a1acb7;--green:#b5df94;--orange:#ffb47d;--red:#f59a9a;--mono:ui-monospace,SFMono-Regular,Menlo,monospace}
*{box-sizing:border-box}[hidden]{display:none!important}body{margin:0;background:var(--bg);color:var(--text);font:15px/1.5 system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif}
main{max-width:1480px;margin:auto;padding:28px 32px 44px}header{display:flex;align-items:center;justify-content:space-between;gap:20px;padding-bottom:22px;border-bottom:1px solid var(--border);margin-bottom:24px}
h1{font-size:29px;letter-spacing:-1px;margin:4px 0 0;font-weight:650}h2{font-size:16px;margin:0;font-weight:600}p{margin:8px 0}.eyebrow{font:11px var(--mono);text-transform:uppercase;letter-spacing:1.8px;color:var(--green)}.muted{color:var(--muted)}.status{display:flex;align-items:center;gap:8px;font:12px var(--mono);padding:8px 12px;border:1px solid var(--border);border-radius:30px;background:var(--panel)}.dot{width:7px;height:7px;background:var(--muted);border-radius:50%}.dot.live{background:var(--green)}.dot.stopped{background:var(--orange)}
.layout{display:grid;grid-template-columns:minmax(0,1.2fr) minmax(350px,.8fr);gap:20px;align-items:start}.panel{background:var(--panel);border:1px solid var(--border);border-radius:12px;overflow:hidden}.heading{display:flex;align-items:center;justify-content:space-between;gap:15px;padding:17px 20px;border-bottom:1px solid var(--border)}.small{font:11px var(--mono);color:var(--muted)}.screen-body{padding:20px;background:#11151a}.screen{position:relative;margin:auto;width:100%;max-width:640px;aspect-ratio:160/144;background:#0b0e10;border:1px solid #41484e;border-radius:5px;overflow:hidden}.screen img{width:100%;height:100%;image-rendering:pixelated;object-fit:contain;display:block}.empty{position:absolute;inset:0;display:flex;align-items:center;justify-content:center;flex-direction:column;text-align:center;padding:32px;background:#10151a}.empty .glyph{color:#48544e;font:66px var(--mono);margin-bottom:20px}.empty strong{font-size:22px;letter-spacing:-.5px}.empty p{max-width:330px;color:var(--muted)}.tag{position:absolute;left:12px;bottom:12px;border-radius:4px;background:#101216ed;padding:5px 8px;color:var(--green);font:11px var(--mono)}.screen-foot{display:flex;align-items:center;justify-content:space-between;flex-wrap:wrap;gap:12px;padding-top:14px;color:var(--muted);font-size:12px}button,a{font:inherit}button{padding:6px 11px;border:1px solid var(--border);background:#232a31;border-radius:6px;color:var(--text);cursor:pointer}button:hover{border-color:var(--green)}button:focus-visible,a:focus-visible{outline:2px solid var(--green);outline-offset:4px}a{color:var(--green);text-decoration:none}a:hover{text-decoration:underline}.screen:fullscreen{max-width:none;width:100vw;height:100vh;border:0;border-radius:0;background:#070907}.screen:fullscreen img{object-fit:contain}
.stack{display:grid;gap:20px}.body{padding:20px}.run-name{color:var(--muted);font:11px var(--mono);overflow-wrap:anywhere;margin-bottom:14px}.progress-top{display:flex;align-items:baseline;justify-content:space-between}.big{font:500 42px/1.1 var(--mono);letter-spacing:-2px}.big small{font-size:19px;color:var(--muted);letter-spacing:-.5px}.bar{height:6px;background:#30363d;border-radius:4px;overflow:hidden;margin:15px 0 20px}.bar i{height:100%;display:block;background:var(--green);width:0}.badges{display:flex;gap:8px;margin-top:11px}.badge{width:24px;height:24px;display:grid;place-items:center;border:1px solid #485057;transform:rotate(45deg);border-radius:5px}.badge span{transform:rotate(-45deg);color:#707981;font:10px var(--mono)}.badge.earned{background:var(--green);border-color:var(--green)}.badge.earned span{color:#182118}.metrics{display:grid;grid-template-columns:1fr 1fr;gap:17px;padding-top:19px;margin-top:19px;border-top:1px solid var(--border)}.metrics label{display:block;color:var(--muted);font-size:12px;margin-bottom:4px}.metrics b{font:500 20px var(--mono)}.activity{font-size:23px;line-height:1.3;letter-spacing:-.5px}.activity-note{color:var(--muted);font-size:13px}.failure{margin-top:15px;padding:13px;background:#382b26;border-left:3px solid var(--orange);border-radius:3px;font-size:13px;color:#f4cfb4;overflow-wrap:anywhere}.counts{display:grid;grid-template-columns:repeat(3,1fr);gap:10px;margin-top:20px}.counts b{display:block;font:20px var(--mono)}.counts span{color:var(--muted);font-size:11px}.pill{font:10px var(--mono);border:1px solid var(--border);border-radius:4px;padding:4px 6px;color:var(--green)}
.bottom{display:grid;grid-template-columns:1fr 1fr;gap:20px;margin-top:20px}.party{display:grid;grid-template-columns:1fr 1fr;gap:10px;padding:16px}.member{padding:12px;border:1px solid var(--border);border-radius:7px}.member-head{display:flex;justify-content:space-between;align-items:center;gap:8px}.member strong{font-size:13px}.member small{color:var(--muted);font:11px var(--mono)}.hp{height:4px;background:#323941;border-radius:3px;margin:10px 0 7px;overflow:hidden}.hp i{display:block;height:100%;background:var(--green)}.member-note{font:10px var(--mono);color:var(--muted)}.table-scroll{overflow:auto;max-height:378px}table{width:100%;border-collapse:collapse;font-size:12px}th{text-align:left;color:var(--muted);font-weight:400;font-size:10px;text-transform:uppercase;letter-spacing:.5px}td,th{padding:11px 15px;border-bottom:1px solid var(--border)}td:first-child{min-width:150px}.by-model{color:var(--green)}.by-support{color:var(--muted)}.outcome{font:10px var(--mono)}.outcome.fail{color:var(--orange)}.empty-party{grid-column:1/-1;padding:22px;color:var(--muted)}footer{display:flex;justify-content:space-between;flex-wrap:wrap;gap:12px;color:var(--muted);font-size:11px;margin-top:23px}.notice{font-size:12px;color:var(--muted);margin-top:16px}.connection-note{color:var(--orange)}
@media(max-width:980px){main{padding:20px}.layout,.bottom{grid-template-columns:1fr}.screen{max-width:550px}.stack{grid-template-columns:1fr 1fr}.counts{gap:5px}}
@media(max-width:630px){main{padding:14px}header{align-items:flex-start;flex-direction:column;gap:14px}h1{font-size:26px}.stack{grid-template-columns:1fr}.body,.heading{padding:16px}.screen-body{padding:12px}.party{grid-template-columns:1fr}.metrics b{font-size:18px}.big{font-size:36px}.bottom{gap:16px}.layout,.stack{gap:16px}}
</style></head><body><main>
<header><div><div class="eyebrow">Local player / Read-only spectator</div><h1>Pokémon Red</h1></div><div class="status" role="status"><i class="dot" id="dot"></i><span id="status">Connecting to viewer</span></div></header>
<div class="layout">
<section class="panel"><div class="heading"><h2>Game screen</h2><span class="small" id="screen-state">Waiting for a real feed</span></div><div class="screen-body">
<div class="screen" id="screen"><img id="frame" alt="Actual emulator screen" hidden><div class="empty" id="empty"><div class="glyph" aria-hidden="true">[ · · ]</div><strong id="empty-title">Waiting for the player</strong><p id="empty-note">Opening this viewer does not start or resume a game.</p></div><div class="tag" id="frame-tag">NO LIVE FEED</div></div>
<div class="screen-foot"><span id="location">Location not yet recorded</span><button id="fullscreen" type="button">Expand screen</button></div>
</div></section>
<div class="stack">
<section class="panel"><div class="heading"><h2>This run</h2><span class="pill">LOCAL MODEL / HYBRID</span></div><div class="body">
<div class="run-name" id="run-name">Checking selected run</div><div class="progress-top"><span class="muted">Pokédex registrations</span><b class="big"><span id="registered">—</span><small> / <span id="target">124</span></small></b></div><div class="bar"><i id="dex-bar"></i></div>
<div class="progress-top"><span class="muted">Gym badges</span><span class="small"><span id="badge-count">—</span> / 8</span></div><div class="badges" id="badges" aria-label="Earned gym badges"></div>
<div class="metrics"><div><label>Money</label><b id="money">—</b></div><div><label>Capture balls</label><b id="balls">—</b></div><div><label>Elapsed real time</label><b id="elapsed">—</b></div><div><label>Recorded goals</label><b id="units">—</b></div></div>
<p class="notice">These are game results, not a percentage of project completion.</p>
</div></section>
<section class="panel"><div class="heading"><h2 id="activity-heading">Current activity</h2><span class="small" id="receipt-age">Awaiting records</span></div><div class="body"><div class="activity" id="activity">Waiting for an observation</div><p class="activity-note" id="activity-note">The player keeps control of every gameplay decision.</p><div class="failure" id="failure" hidden></div><div class="counts"><div><b id="model-count">—</b><span>Model choices</span></div><div><b id="support-count">—</b><span>Support steps</span></div><div><b id="setbacks">—</b><span>Safe setbacks</span></div></div></div></section>
</div></div>
<div class="bottom">
<section class="panel"><div class="heading"><h2>Party</h2><span class="small">LAST RECORDED BOUNDARY</span></div><div class="party" id="party"><p class="empty-party">Party details have not been recorded yet.</p></div></section>
<section class="panel"><div class="heading"><h2>Recent decisions</h2><span class="small">NEWEST FIRST</span></div><div class="table-scroll"><table><thead><tr><th>Goal</th><th>Chosen by</th><th>Result</th><th>Time</th></tr></thead><tbody id="recent"><tr><td colspan="4" class="muted">No recorded choices yet.</td></tr></tbody></table></div></section>
</div>
<footer><span>No game controls · No save editing · No runtime LLM calls from this viewer</span><span id="updated">Waiting for recorded data</span><a href="/">Detailed observer view</a></footer>
</main><script>
const $=id=>document.getElementById(id),fmt=n=>Number(n||0).toLocaleString();
const text=(id,value)=>$(id).textContent=value;
const count=(run,key)=>run.counts_observed?fmt(run[key]):run[key]?`≥${fmt(run[key])}`:'—';
let lastFrame=-1;
function duration(seconds){const n=Math.max(0,Math.floor(seconds||0));return n>=3600?`${Math.floor(n/3600)}h ${Math.floor(n%3600/60)}m`:`${Math.floor(n/60)}m ${n%60}s`;}
function clock(value){if(!value)return 'Not recorded';const d=new Date(value);return Number.isNaN(d.getTime())?'Not recorded':d.toLocaleTimeString([],{hour:'numeric',minute:'2-digit',second:'2-digit'});}
function runName(id){const m=/red-frozen-autonomous-run-(\d{4})(\d{2})(\d{2})-(v\d+)/.exec(id||'');return m?`Frozen run ${m[4]} · ${m[2]}/${m[3]}/${m[1]}`:id||'Selected run';}
const badgeNames=['Boulder','Cascade','Thunder','Rainbow','Soul','Marsh','Volcano','Earth'];
badgeNames.forEach((name,i)=>{const badge=document.createElement('div');badge.className='badge';badge.id=`badge-${i}`;badge.title=name;const label=document.createElement('span');label.textContent=i+1;badge.append(label);$('badges').append(badge);});
function render(data){
 const run=data.run||{},signal=data.dashboard||{},live=run.lifecycle==='running',stopped=run.lifecycle==='stopped';
 text('status',stopped?'Player stopped':live?'Player running':'No running player');$('dot').className=`dot ${stopped?'stopped':live?'live':''}`;
 text('run-name',runName(run.id));text('registered',data.collection.observed?fmt(data.collection.registered):'—');text('target',fmt(data.collection.target));$('dex-bar').style.width=`${data.collection.observed?100*data.collection.registered/data.collection.target:0}%`;
 text('badge-count',run.badges??'—');badgeNames.forEach((name,i)=>{$(`badge-${i}`).className=`badge${run.badge_bits&(1<<i)?' earned':''}`;$(`badge-${i}`).setAttribute('aria-label',`${name}: ${run.badge_bits&(1<<i)?'earned':'not earned'}`);});
 text('money',run.money==null?'—':`₽${fmt(run.money)}`);text('balls',run.balls??'—');text('elapsed',duration(run.elapsed_seconds));text('units',run.units??'—');text('location',data.location||'Location not yet recorded');
 text('activity-heading',stopped?'Last activity':'Current activity');text('activity',run.activity||data.stage);text('activity-note',stopped?'This is the retained result. The viewer has not restarted the save.':live?'The player chooses and executes goals locally.':'Opening the viewer does not launch gameplay.');
 $('failure').hidden=!run.failure&&!stopped;text('failure',run.failure||`Stopped: ${(run.terminal_reason||'worker ended').replaceAll('_',' ')}`);text('model-count',count(run,'model_decisions'));text('support-count',count(run,'support_decisions'));text('setbacks',count(run,'ordinary_setbacks'));text('receipt-age',`Recorded ${clock(run.recorded_at_utc)}`);text('updated',`Checkpoint ${clock(run.recorded_at_utc)} · parameter updates: ${run.weights_updated??'not reported'}`);
 const frameLive=live&&signal.frame_ready&&run.frame_source_connected!==false&&signal.frame_age_seconds<3;
 const frameLabel=frameLive?'LIVE EMULATOR':signal.frame_ready?'LAST REAL FRAME':stopped?'RUN STOPPED / NO FRAME':'NO LIVE FEED';
 text('frame-tag',frameLabel);text('screen-state',frameLive?'Real frames · view only':signal.frame_ready?'Retained frame · not live':stopped?'Stopped checkpoint':'Waiting for the screen publisher');
 $('empty').hidden=Boolean(signal.frame_ready);$('frame').hidden=!signal.frame_ready;
 text('empty-title',stopped?'The player is stopped':live?'Player running · screen not connected':'No player connected');text('empty-note',stopped?'The retained progress and decisions are shown alongside. No emulator is running.':live?'This launch is not publishing fresh screen frames to the viewer.':'This spectator view never launches or resumes a save.');
 if(signal.frame_ready&&signal.frame_version!==lastFrame){lastFrame=signal.frame_version;$('frame').src=`/frame.png?v=${lastFrame}`;}
 const party=$('party');party.replaceChildren();if(!(data.party||[]).length){const p=document.createElement('p');p.className='empty-party';p.textContent='Party details have not been recorded yet.';party.append(p);}
 (data.party||[]).forEach(member=>{const item=document.createElement('div');item.className='member';const top=document.createElement('div');top.className='member-head';const name=document.createElement('strong');name.textContent=member.label;const level=document.createElement('small');level.textContent=`Lv ${member.level}`;top.append(name,level);const bar=document.createElement('div');bar.className='hp';const fill=document.createElement('i');fill.style.width=`${100*member.hp_ratio}%`;if(member.hp_ratio<.25)fill.style.background='var(--red)';else if(member.hp_ratio<.5)fill.style.background='var(--orange)';bar.append(fill);const detail=document.createElement('div');detail.className='member-note';detail.textContent=`${member.hp} / ${member.max_hp} HP · ${member.status}`;item.append(top,bar,detail);party.append(item);});
 const recent=$('recent');recent.replaceChildren();const rows=(run.recent||[]).slice().reverse();if(!rows.length){const row=document.createElement('tr'),cell=document.createElement('td');cell.colSpan=4;cell.className='muted';cell.textContent='No recorded choices yet.';row.append(cell);recent.append(row);}rows.forEach(event=>{const row=document.createElement('tr');[event.goal,event.authority,event.result,event.result==='In progress'?'—':`${Number(event.seconds).toFixed(1)}s`].forEach((value,i)=>{const cell=document.createElement('td');cell.textContent=value;if(i===1)cell.className=event.authority==='Model'?'by-model':'by-support';if(i===2)cell.className=`outcome ${['Failed','Safe setback'].includes(event.result)?'fail':''}`;row.append(cell);});recent.append(row);});
}
async function refresh(){try{const response=await fetch('/api/status',{cache:'no-store',signal:AbortSignal.timeout(4000)});if(!response.ok)throw Error('status unavailable');render(await response.json());}catch{text('status','Viewer disconnected');$('dot').className='dot stopped';text('frame-tag','DISCONNECTED / LAST FRAME');text('screen-state','No current connection');}finally{setTimeout(refresh,750);}}
$('fullscreen').addEventListener('click',async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else await $('screen').requestFullscreen();}catch{text('screen-state','Fullscreen unavailable in this browser');}});
refresh();
</script></body></html>""".encode()
